  black: "#10222e",
  grey: "#8a97a0",
  silver: "#c9d3da",
  red: "#e5484d",
  orange: "#ff8a1f",
  yellow: "#ffd23f",
  gold: "#d4a017",
  green: "#3fb950",
  teal: "#12a594",
  blue: "#3b82f6",
  purple: "#8e4ec6",
  pink: "#ff6fae",
  brown: "#8b5a2b",
  sand: "#e8d9a8",
