  const problems = Object.values(failed);
  const checks = CHECKS.map((name) => {
    const mine = problems.filter((problem) => problem.name === name);
    const detail = mine.map((p) => (p.kind ? p.kind + ": " : "") + (p.detail || p.times + " times")).join("; ");
