import { glide, step, wander } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";
import { seconds } from "../world/time.js";

const SHELL = "orange";
const LEGS = "pink";

const DART_INTERVAL = seconds(2);
const DART_ENERGY = 5;
const DART_PUSH = 2.5;

export function spawn() {
  return { energy: ENERGY_MAX, nextDart: DART_INTERVAL };
}

export function update(shrimp, world) {
  shrimp.nextDart -= 1;

  if (shrimp.nextDart <= 0 && shrimp.energy > DART_ENERGY) {
    drain(shrimp, DART_ENERGY);
    wander(shrimp, DART_PUSH);
    shrimp.nextDart = DART_INTERVAL;
  } else {
    glide(shrimp, 0.9);
  }

  step(shrimp);
  keepInside(shrimp);
}

export function draw(shrimp, pen) {
  if (shrimp.vx < 0) pen.flip();

  pen.fill(LEGS);
  for (let i = -2; i <= 2; i += 1) {
    pen.line(i * 4, 5, i * 4 - 3, 12);
  }

  pen.fill(SHELL);
  pen.ellipse(0, 0, 18, 8);
  pen.ellipse(-10, -4, 12, 6);

  pen.fill(LEGS);
  pen.poly([14, 0, 26, -10, 26, 10]);

  pen.fill("black");
  pen.circle(12, -4, 2);
}
